  "implementation": "def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    # Build node map and children list
    node_map = {node['id']: node for node in nodes}
    children = {node['id']: [] for node in nodes}
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children[parent].append(node['id'])
    root_id = 'root'
    from collections import deque
    removed = set()
    # BFS queue: (node_id, parent_removed_flag)
    q = deque()
    q.append((root_id, False))
    while q:
        nid, parent_removed = q.popleft()
        node = node_map[nid]
        if parent_removed:
            removed.add(nid)
            # all children are removed as well
            for cid in children[nid]:
                q.append((cid, True))
        else:
            if node['removable'] and node['utility'] < threshold:
                removed.add(nid)
                for cid in children[nid]:
                    q.append((cid, True))
            else:
                for cid in children[nid]:
                    q.append((cid, False))
    # Return a JSON-serializable object
    return {'removed': sorted(list(removed))}"
}
